/**
 * 저장과 새 도면: QSAVE, SAVE, SAVEAS, NEW
 * 파일은 이 컴퓨터에서 만든다(서버 없음). 브라우저가 파일 시스템 접근을 허락하면 고른 파일에 바로 쓰고,
 * 아니면 내려받기로 저장한다.
 */
import { syncActiveVports } from './vports';
import { trackExport } from 'opencad-site-kit/analytics';
import { forgetRecovery } from './autosave';
import { createNewDocument } from '../core/newdoc';
import type { CadDocument } from '../core/model';
import { pickFiles, readDrawingFile } from './drawingfiles';
import type { SaveFormat } from '../worker/protocol';
import type { App, CommandContext } from './app';
import type { DocState } from './docstate';
import { baseName, download } from './export';
import { form, h } from './ui/dom';
import { prefGet, resultDialog } from './mgr-ui';
import { type SaveLoss, saveLosses, saveLossLines } from './saveloss';
import { commandLineMode, inScript } from './script';

interface SaveTarget {
  format: SaveFormat;
  version: string;
  binary: boolean;
  /** 파일 확장자가 형식과 다를 때(도면 템플릿 .dwt) */
  ext?: 'dwt';
  /** 파일 시스템 접근 API로 고른 파일(있으면 QSAVE가 그 파일에 바로 쓴다) */
  handle?: FileSystemFileHandleLike;
}

/** 브라우저 파일 시스템 접근 API 중 쓰는 부분 */
interface FileSystemFileHandleLike {
  name: string;
  createWritable(): Promise<{ write(data: Blob): Promise<void>; close(): Promise<void> }>;
}
type SavePicker = (opt: { suggestedName?: string; types?: { description: string; accept: Record<string, string[]> }[] }) => Promise<FileSystemFileHandleLike>;

export const SAVE_TYPES: { value: string; label: string; format: SaveFormat; version: string }[] = [
  { value: 'dwg-AC1032', label: 'AutoCAD 2018/LT2018 도면 (*.dwg)', format: 'dwg', version: 'AC1032' },
  { value: 'dwg-AC1027', label: 'AutoCAD 2013/LT2013 도면 (*.dwg)', format: 'dwg', version: 'AC1027' },
  { value: 'dwg-AC1024', label: 'AutoCAD 2010/LT2010 도면 (*.dwg)', format: 'dwg', version: 'AC1024' },
  { value: 'dwg-AC1018', label: 'AutoCAD 2004/LT2004 도면 (*.dwg)', format: 'dwg', version: 'AC1018' },
  { value: 'dwg-AC1015', label: 'AutoCAD 2000/LT2000 도면 (*.dwg)', format: 'dwg', version: 'AC1015' },
  { value: 'dxf-AC1032', label: 'AutoCAD 2018 DXF (*.dxf)', format: 'dxf', version: 'AC1032' },
  { value: 'dxf-AC1027', label: 'AutoCAD 2013/LT2013 DXF (*.dxf)', format: 'dxf', version: 'AC1027' },
  { value: 'dxf-AC1024', label: 'AutoCAD 2010/LT2010 DXF (*.dxf)', format: 'dxf', version: 'AC1024' },
  { value: 'dxf-AC1021', label: 'AutoCAD 2007/LT2007 DXF (*.dxf)', format: 'dxf', version: 'AC1021' },
  { value: 'dxf-AC1018', label: 'AutoCAD 2004/LT2004 DXF (*.dxf)', format: 'dxf', version: 'AC1018' },
  { value: 'dxf-AC1015', label: 'AutoCAD 2000/LT2000 DXF (*.dxf)', format: 'dxf', version: 'AC1015' },
  { value: 'dxf-AC1009', label: 'AutoCAD R12/LT2 DXF (*.dxf)', format: 'dxf', version: 'AC1009' },
];

/** 다른 이름으로 저장의 도면 템플릿(DWG 2018 내용, 확장자 .dwt). 다른 명령의 형식 목록에는 넣지 않는다 */
const TEMPLATE_TYPE = { value: 'dwt-AC1032', label: 'AutoCAD 도면 템플릿 (*.dwt)', format: 'dwg' as SaveFormat, version: 'AC1032' };

const targets = new WeakMap<DocState, SaveTarget>();

/** 저장한 뒤 알림(REVERT가 마지막으로 저장한 내용을 기억한다) */
export const savedListeners = new Set<(st: DocState, data: Blob, name: string) => void>();

/** 열린 파일과 같은 형식으로 저장할 수 있으면 그 설정 */
export function sameFormat(st: DocState): SaveTarget | null {
  const d = st.doc;
  if (d.format === 'dwg') {
    // R2007은 쓸 수 없어 R2004로, R12·R13·R14는 R2000으로
    const v = d.version === 'AC1021' ? 'AC1018' : d.version === 'AC1009' || d.version === 'AC1012' || d.version === 'AC1014' ? 'AC1015' : d.version;
    const t = SAVE_TYPES.find((x) => x.format === 'dwg' && x.version === v);
    return { format: 'dwg', version: t ? t.version : 'AC1032', binary: false };
  }
  if (d.format !== 'dxf') return null;
  const t = SAVE_TYPES.find((x) => x.format === 'dxf' && x.version === d.version);
  return { format: 'dxf', version: t ? t.version : 'AC1032', binary: !!d.binary };
}

function fileName(st: DocState, t: SaveTarget): string {
  return `${baseName(st.saveName)}.${t.ext ?? t.format}`;
}

/** 실제로 쓰기 */
async function write(app: App, ctx: CommandContext, st: DocState, t: SaveTarget, name: string): Promise<boolean> {
  await app.edits.flush(st);
  // 다시 열 때 같은 화면·타일 뷰포트로 열리게 *Active 뷰를 지금 화면으로
  syncActiveVports(app, st);
  ctx.print(`${name} 저장하는 중…`);
  app.ui.setBusy('저장하는 중…', 0.5);
  let res;
  try {
    res = await app.engine.save(st.docId, t.format, t.version, t.binary);
  } catch (e) {
    ctx.print(`저장하지 못했습니다: ${e instanceof Error ? e.message : String(e)}`, 'err');
    return false;
  } finally {
    app.ui.setBusy(null);
  }
  // 빠지거나 바뀌는 것이 있으면 파일을 내기 전에 묻는다(원본 파일은 바꾸지 않는다)
  const losses = saveLosses(res.warnings);
  if (losses.length && !(await confirmSaveLosses(app, ctx, st, t, losses))) {
    ctx.print('저장을 취소했습니다.');
    return false;
  }
  const blob = new Blob([res.data as BlobPart], { type: t.format === 'dxf' ? 'application/dxf' : 'application/acad' });
  if (t.handle) {
    try {
      const w = await t.handle.createWritable();
      await w.write(blob);
      await w.close();
      trackExport(t.format);
    } catch (e) {
      ctx.print(`파일에 쓰지 못해 내려받기로 저장합니다: ${e instanceof Error ? e.message : String(e)}`, 'err');
      t.handle = undefined;
      download(blob, name);
    }
  } else download(blob, name);
  st.saveName = name;
  st.session.markSaved();
  for (const f of savedListeners) f(st, blob, name);
  // 저장했으니 자동 저장본은 필요 없다
  forgetRecovery(st);
  targets.set(st, t);
  app.ui.refreshTabs();
  document.title = `${st.saveName} - OpenCAD DWG·DXF`;
  const label = t.ext === 'dwt' ? TEMPLATE_TYPE.label : (SAVE_TYPES.find((x) => x.format === t.format && x.version === t.version)?.label ?? t.version);
  ctx.print(`${name}을(를) ${label}${t.binary ? ' 이진' : ''} 형식으로 저장했습니다(${(res.data.byteLength / 1024).toFixed(0)} KB, ${Math.round(res.ms)}ms).`);
  for (const w of res.warnings.slice(0, 5)) ctx.print(`참고: ${w.message}${w.count ? ` (${w.count})` : ''}`);
  return true;
}

/**
 * 저장 전 확인: 이 형식·버전으로 쓰면 빠지거나 바뀌는 것을 보이고 계속할지 묻는다.
 * 스크립트 안에서는 묻지 않고(입력 줄을 먹지 않게) 명령행에 적기만 한다. CMDDIA 0이면 명령행으로 묻는다.
 */
async function confirmSaveLosses(app: App, ctx: CommandContext, st: DocState, t: SaveTarget, losses: SaveLoss[]): Promise<boolean> {
  const label = SAVE_TYPES.find((x) => x.format === t.format && x.version === t.version)?.label ?? t.version;
  const orig = st.doc.format === 'dwg' ? SAVE_TYPES.find((x) => x.format === 'dwg' && x.version === st.doc.version) : st.doc.format === 'dxf' ? SAVE_TYPES.find((x) => x.format === 'dxf' && x.version === st.doc.version) : undefined;
  const hint = orig && (orig.format !== t.format || orig.version !== t.version) ? orig.label : null;
  const lines = saveLossLines(losses);
  if (inScript(app)) {
    for (const l of lines) ctx.print(`참고: ${l}`);
    return true;
  }
  if (commandLineMode(app)) {
    ctx.print(`${label}(으)로 저장하면 다음이 빠지거나 바뀝니다:`);
    for (const l of lines) ctx.print(`  ${l}`);
    if (hint) ctx.print(`원래 형식(${hint})으로 저장하면 남습니다.`);
    const r = await ctx.getPoint('그래도 저장하시겠습니까? [예(Y)/아니요(N)] <아니요>:', { keywords: [{ key: 'Y', label: '예' }, { key: 'N', label: '아니요' }] });
    return 'keyword' in r && r.keyword === 'Y';
  }
  const list = h(
    'ul',
    { class: 'save-loss' },
    ...losses.map((l) =>
      h('li', {}, h('span', {}, l.converted ? '바뀜: ' : '빠짐: '), h('span', {}, l.message), h('span', { translate: 'no' }, ` (${l.count})${l.types.length ? ` ${l.types.slice(0, 8).join(', ')}${l.types.length > 8 ? ' …' : ''}` : ''}`)),
    ),
  );
  const body = h(
    'div',
    {},
    h('div', { class: 'mgr-note', 'data-i18n-ui-copy': '' }, `${label}(으)로 저장하면 다음이 빠지거나 바뀝니다. 열어 둔 도면과 원본 파일은 그대로입니다.`),
    list,
    hint ? h('div', { class: 'mgr-note', 'data-i18n-ui-copy': '' }, `원래 형식(${hint})으로 저장하면 남습니다.`) : null,
  );
  const ok = await resultDialog('저장 전 확인', body, { ok: '그래도 저장', width: 560, submit: () => true });
  return ok === true;
}

async function saveAs(app: App, ctx: CommandContext): Promise<void> {
  const st = app.active!;
  // OPTIONS › 열기 및 저장 › 다른 이름으로 저장 형식을 정했으면 그것이 기본(이 도면을 이미 저장한 형식이 먼저)
  const opt = SAVE_TYPES.find((x) => x.value === prefGet('opencad.options.saveType'));
  const prev = targets.get(st) ?? (opt ? { format: opt.format, version: opt.version, binary: false } : sameFormat(st));
  const picker = (window as unknown as { showSaveFilePicker?: SavePicker }).showSaveFilePicker;
  const v = await form(
    '다른 이름으로 저장',
    [
      ...(picker ? [] : [{ key: 'name', label: '파일 이름', type: 'text' as const, value: baseName(st.saveName), wide: true }]),
      { key: 'type', label: '파일 유형', type: 'select', value: prev ? (prev.ext === 'dwt' ? TEMPLATE_TYPE.value : `${prev.format}-${prev.version}`) : 'dwg-AC1032', options: [...SAVE_TYPES, TEMPLATE_TYPE].map((x) => ({ value: x.value, label: x.label })) },
      { key: 'binary', label: '이진 DXF(DXF일 때)', type: 'check', value: prev?.binary ?? false },
    ],
    {
      ok: '저장',
      note: '파일은 서버로 보내지 않고 이 컴퓨터에서 만듭니다. DWG R2007(AC1021) 형식은 R2004로 저장합니다.',
      validate: (x) => (picker || String(x.name ?? '').trim() ? null : '파일 이름을 입력하십시오.'),
    },
  );
  if (!v) return;
  const type = [...SAVE_TYPES, TEMPLATE_TYPE].find((x) => x.value === v.type) ?? SAVE_TYPES[0]!;
  const t: SaveTarget = { format: type.format, version: type.version, binary: !!v.binary && type.format === 'dxf', ext: type === TEMPLATE_TYPE ? 'dwt' : undefined };
  let name = picker ? fileName(st, t) : `${String(v.name).trim().replace(/\.(dxf|dwg|dwt)$/i, '')}.${t.ext ?? t.format}`;
  if (picker) {
    try {
      const handle = await picker({ suggestedName: name, types: [{ description: type.label, accept: t.ext === 'dwt' ? { 'application/acad': ['.dwt'] } : type.format === 'dwg' ? { 'application/acad': ['.dwg'] } : { 'application/dxf': ['.dxf'] } }] });
      t.handle = handle;
      name = handle.name;
    } catch {
      ctx.print('저장을 취소했습니다.');
      return;
    }
  }
  await write(app, ctx, st, t, name);
}

let drawingSerial = 1;

function lastUnits(): 'metric' | 'imperial' {
  try {
    return localStorage.getItem('opencad.newUnits') === 'imperial' ? 'imperial' : 'metric';
  } catch {
    return 'metric';
  }
}

/** 문서 하나를 QSAVE처럼 저장한다(형식을 모르면 그 문서를 활성으로 하고 다른 이름으로 저장 상자). 저장했으면 true */
export async function quickSave(app: App, ctx: CommandContext, st: DocState): Promise<boolean> {
  const t = targets.get(st) ?? sameFormat(st);
  if (!t) {
    if (app.active !== st) app.activate(st);
    await saveAs(app, ctx);
    return !st.session.dirty;
  }
  return write(app, ctx, st, t, t.handle?.name ?? fileName(st, t));
}

export function registerSaveCommands(app: App): void {
  app.register({
    name: 'QSAVE',
    title: '저장',
    async run(ctx) {
      // FIELDEVAL 저장 비트: 저장하기 전에 필드를 다시 계산한다(fieldcmds는 app.ts와 순환하므로 동적으로)
      (await import('./fieldcmds')).updateFieldsOn(app, 'save', { fileName: app.active!.saveName });
      await quickSave(app, ctx, app.active!);
    },
  });
  app.register({
    name: 'SAVEAS',
    aliases: ['SAVE', 'DXFOUT'],
    title: '다른 이름으로 저장',
    async run(ctx) {
      (await import('./fieldcmds')).updateFieldsOn(app, 'save', { fileName: app.active!.saveName });
      await saveAs(app, ctx);
    },
  });

  app.register({
    name: 'NEW',
    aliases: ['QNEW'],
    title: '새 도면',
    noDoc: true,
    async run(ctx, arg) {
      // 시작 화면 단추·스크립트는 서식을 인자로 넘겨 대화상자 없이 만든다(NEW metric · NEW imperial)
      const given = arg?.trim().toLowerCase();
      const v = given === 'metric' || given === 'imperial' ? { units: given } : await form(
        '새 도면',
        [
          {
            key: 'units',
            label: '템플릿',
            type: 'select',
            value: lastUnits(),
            options: [
              { value: 'metric', label: 'acadiso (미터법, 밀리미터)' },
              { value: 'imperial', label: 'acad (영국식, 인치)' },
              { value: 'file', label: '템플릿 파일 찾아보기… (*.dwt, *.dwg, *.dxf)' },
            ],
          },
        ],
        { ok: '만들기' },
      );
      if (!v) return;
      let name: string;
      do name = `Drawing${drawingSerial++}.dwg`;
      while (app.docs.some((d) => d.saveName === name));
      // 템플릿 파일: 그 도면의 내용·설정으로 이름 없는 새 도면을 만든다(저장하면 이름을 묻는다)
      if (v.units === 'file') {
        const [f] = await pickFiles('.dwt,.dwg,.dxf,.DWT,.DWG,.DXF', false);
        if (!f) return;
        let doc: CadDocument;
        try {
          doc = (await readDrawingFile(app, f)).doc;
        } catch (e) {
          ctx.print(`${f.name}을(를) 읽지 못했습니다: ${e instanceof Error ? e.message : String(e)}`, 'err');
          return;
        } finally {
          app.ui.setBusy(null);
        }
        const fresh = structuredClone(doc);
        fresh.format = 'new';
        const now = Date.now() / 86400000 + 2440587.5;
        for (const k of ['$TDCREATE', '$TDUCREATE', '$TDUPDATE', '$TDUUPDATE']) fresh.header.set(k, now);
        fresh.header.set('$TDINDWG', 0);
        const res = await app.engine.adopt(name, fresh);
        app.addDocument(res, name, 0);
        ctx.print(`템플릿 ${f.name}(으)로 새 도면 ${name}을(를) 만들었습니다.`);
        return;
      }
      const units = v.units === 'imperial' ? 'imperial' : 'metric';
      try {
        localStorage.setItem('opencad.newUnits', units);
      } catch {
        /* 저장소를 못 쓰면 기억하지 않는다 */
      }
      const doc = createNewDocument(units);
      const res = await app.engine.adopt(name, doc);
      app.addDocument(res, name, 0);
      ctx.print(`새 도면 ${name}을(를) 만들었습니다(${units === 'metric' ? 'acadiso, mm' : 'acad, inch'}).`);
    },
  });
}
